CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "profile_text" text, "location" varchar, "created_at" datetime, "updated_at" datetime, "headline" varchar, "aspirations" text, "zip_code" varchar, "radius" integer not null default '20', "phone" varchar, "avatar" varchar, "linkedin_url" varchar, "github_url" varchar, "portfolio_url" varchar, "birth_date" date, "availability_status" varchar, "links" text, "daily_ai_limit" integer not null default '15', "daily_ai_usage" integer not null default '0', "last_seen_at" datetime, "last_ai_usage_at" datetime);
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE "metiers" ("id" integer primary key autoincrement not null, "code" varchar not null, "guid" varchar, "label" varchar not null, "created_at" datetime, "updated_at" datetime, "slug" varchar);
CREATE TABLE "skills" ("id" integer primary key autoincrement not null, "code" varchar not null, "label" varchar not null, "type" varchar check ("type" in ('hard', 'soft')) not null, "created_at" datetime, "updated_at" datetime, "slug" varchar);
CREATE TABLE "sectors" ("id" integer primary key autoincrement not null, "label" varchar not null, "created_at" datetime, "updated_at" datetime, "slug" varchar);
CREATE TABLE "employers" ("id" integer primary key autoincrement not null, "id_forem" varchar, "label" varchar not null, "logo_uuid" varchar, "logo_base64" text, "logo_mime_type" varchar, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "sources" ("id" integer primary key autoincrement not null, "code" varchar not null, "label" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "benefits" ("id" integer primary key autoincrement not null, "code" varchar not null, "label" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "languages" ("id" integer primary key autoincrement not null, "code" varchar not null, "label" varchar not null, "created_at" datetime, "updated_at" datetime, "slug" varchar);
CREATE TABLE "permits" ("id" integer primary key autoincrement not null, "code" varchar not null, "label" varchar not null, "value" varchar not null, "created_at" datetime, "updated_at" datetime, "slug" varchar);
CREATE TABLE "studies" ("id" integer primary key autoincrement not null, "label" varchar not null, "created_at" datetime, "updated_at" datetime, "slug" varchar);
CREATE TABLE "job_offer_skill" ("job_offer_id" integer not null, "skill_id" integer not null, "is_required" tinyint(1) not null default '0', foreign key("job_offer_id") references "job_offers"("id") on delete cascade, foreign key("skill_id") references "skills"("id") on delete cascade, primary key ("job_offer_id", "skill_id"));
CREATE TABLE "job_offer_language" ("job_offer_id" integer not null, "language_id" integer not null, "level" varchar, "is_required" tinyint(1) not null default '1', foreign key("job_offer_id") references "job_offers"("id") on delete cascade, foreign key("language_id") references "languages"("id") on delete cascade, primary key ("job_offer_id", "language_id"));
CREATE TABLE "job_offer_permit" ("job_offer_id" integer not null, "permit_id" integer not null, "is_required" tinyint(1) not null default '1', foreign key("job_offer_id") references "job_offers"("id") on delete cascade, foreign key("permit_id") references "permits"("id") on delete cascade, primary key ("job_offer_id", "permit_id"));
CREATE TABLE "job_offer_benefit" ("job_offer_id" integer not null, "benefit_id" integer not null, foreign key("job_offer_id") references "job_offers"("id") on delete cascade, foreign key("benefit_id") references "benefits"("id") on delete cascade, primary key ("job_offer_id", "benefit_id"));
CREATE TABLE "job_offer_sector" ("job_offer_id" integer not null, "sector_id" integer not null, foreign key("job_offer_id") references "job_offers"("id") on delete cascade, foreign key("sector_id") references "sectors"("id") on delete cascade, primary key ("job_offer_id", "sector_id"));
CREATE TABLE "job_offer_study" ("job_offer_id" integer not null, "study_id" integer not null, foreign key("job_offer_id") references "job_offers"("id") on delete cascade, foreign key("study_id") references "studies"("id") on delete cascade, primary key ("job_offer_id", "study_id"));
CREATE TABLE "job_offer_experience" ("id" integer primary key autoincrement not null, "job_offer_id" integer not null, "metier_id" integer not null, "is_required" tinyint(1) not null default '0', "experience_label" varchar, "created_at" datetime, "updated_at" datetime, foreign key("job_offer_id") references "job_offers"("id") on delete cascade, foreign key("metier_id") references "metiers"("id") on delete cascade);
CREATE TABLE "user_skill" ("user_id" integer not null, "skill_id" integer not null, "level" varchar check ("level" in ('beginner', 'intermediate', 'advanced', 'expert')), "created_at" datetime, "updated_at" datetime, "status" varchar not null default 'active', foreign key("user_id") references "users"("id") on delete cascade, foreign key("skill_id") references "skills"("id") on delete cascade, primary key ("user_id", "skill_id"));
CREATE TABLE "user_language" ("user_id" integer not null, "language_id" integer not null, "level" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("language_id") references "languages"("id") on delete cascade, primary key ("user_id", "language_id"));
CREATE TABLE "user_permit" ("user_id" integer not null, "permit_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("permit_id") references "permits"("id") on delete cascade, primary key ("user_id", "permit_id"));
CREATE TABLE "user_matches" ("id" integer primary key autoincrement not null, "user_id" integer not null, "job_offer_id" integer not null, "pre_score" integer, "ai_score" integer, "final_score" integer, "strengths" text, "weaknesses" text, "ai_raw_response" text, "analyzed_at" datetime, "created_at" datetime, "updated_at" datetime, "ai_analysis_narrative" text, "ai_recommendation" text, "ai_status" varchar not null default 'idle', "pre_score_details" text, foreign key("user_id") references "users"("id") on delete cascade, foreign key("job_offer_id") references "job_offers"("id") on delete cascade);
CREATE TABLE "job_offers" ("id" integer primary key autoincrement not null, "forem_id" integer not null, "forem_ref" varchar not null, "title" varchar not null, "metier_id" integer, "employer_id" integer not null, "source_id" integer, "description" text, "contract_type" varchar not null, "working_regime" varchar not null, "working_regime_detail" varchar, "working_hours" numeric, "shift_period" varchar, "base_salary" varchar, "benefits_comments" text, "nombre_postes" integer not null default ('1'), "location" varchar, "locations_json" text, "contact_name" varchar, "contact_email" varchar, "contact_phone" varchar, "apply_instructions" text, "is_postulable" tinyint(1) not null default ('0'), "start_date" date, "published_at" datetime, "expires_at" date, "raw_data" text, "created_at" datetime, "updated_at" datetime, "is_detailed" tinyint(1) not null default ('0'), "apply_url" varchar, "travel_info" varchar, "status" varchar not null default 'active', "last_seen_at" datetime, "detailed_at" datetime, "content_hash" varchar, "latitude" numeric, "longitude" numeric, foreign key("source_id") references sources("id") on delete no action on update no action, foreign key("employer_id") references employers("id") on delete no action on update no action, foreign key("metier_id") references metiers("id") on delete no action on update no action);
CREATE TABLE "profile_messages" ("id" integer primary key autoincrement not null, "user_id" integer not null, "role" varchar not null, "content" text not null, "created_at" datetime, "updated_at" datetime, "session_id" varchar, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "profile_sessions" ("id" varchar not null, "user_id" integer not null, "title" varchar, "is_archived" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, primary key ("id"));
CREATE TABLE "user_metier" ("user_id" integer not null, "metier_id" integer not null, "created_at" datetime, "updated_at" datetime, "status" varchar not null default 'favorite', foreign key("user_id") references "users"("id") on delete cascade, foreign key("metier_id") references "metiers"("id") on delete cascade, primary key ("user_id", "metier_id"));
CREATE TABLE "referentiel_metiers" ("id" integer primary key autoincrement not null, "code" varchar not null, "title" varchar not null, "description" text, "family_name" varchar, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime);
CREATE TABLE "user_preferred_referentiel" ("id" integer primary key autoincrement not null, "user_id" integer not null, "referentiel_metier_id" integer not null, "created_at" datetime, "updated_at" datetime, "status" varchar not null default 'favorite', foreign key("user_id") references "users"("id") on delete cascade, foreign key("referentiel_metier_id") references "referentiel_metiers"("id") on delete cascade);
CREATE TABLE "discovery_suggestions" ("id" integer primary key autoincrement not null, "user_id" integer not null, "code" varchar not null, "title" varchar not null, "reason" text not null, "type" varchar not null default 'aligned', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "zip_codes" ("id" integer primary key autoincrement not null, "zip_code" varchar not null, "city" varchar not null, "latitude" numeric not null, "longitude" numeric not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "user_feedback" ("id" integer primary key autoincrement not null, "user_id" integer, "message" text not null, "page_url" varchar, "type" varchar not null default 'feedback', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "user_facts" ("id" integer primary key autoincrement not null, "user_id" integer not null, "content" text, "category" varchar, "status" varchar not null default ('draft'), "confidence_score" float, "source_metadata" text, "created_at" datetime, "updated_at" datetime, "session_id" varchar, "is_locked" tinyint(1) not null default ('0'), "proposed_content" text, "proposed_category" varchar, "proposed_action" varchar, "experience_id" integer, "local_id" integer, foreign key("experience_id") references experiences("id") on delete set null on update no action, foreign key("user_id") references users("id") on delete cascade on update no action);
CREATE TABLE "experiences" ("id" integer primary key autoincrement not null, "user_id" integer not null, "company" varchar, "title" varchar, "description" text, "location" varchar, "start_date" date, "end_date" date, "is_current" tinyint(1) not null default ('0'), "created_at" datetime, "updated_at" datetime, "status" varchar not null default ('validated'), "proposed_action" varchar, "employment_type" varchar, "company_logo" varchar, "proposed_data" text, foreign key("user_id") references users("id") on delete cascade on update no action);
CREATE TABLE "education" ("id" integer primary key autoincrement not null, "user_id" integer not null, "school" varchar, "degree" varchar, "field" varchar, "graduation_year" integer, "description" text, "created_at" datetime, "updated_at" datetime, "status" varchar not null default ('validated'), "proposed_action" varchar, "start_date" date, "grade" varchar, "proposed_data" text, foreign key("user_id") references users("id") on delete cascade on update no action);
CREATE TABLE "projects" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar, "description" text, "url" varchar, "start_date" date, "end_date" date, "is_ongoing" tinyint(1) not null default ('0'), "created_at" datetime, "updated_at" datetime, "status" varchar not null default ('validated'), "proposed_data" text, "proposed_action" varchar, foreign key("user_id") references users("id") on delete cascade on update no action);
CREATE TABLE "certifications" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar, "issuing_organization" varchar, "issue_date" date, "expiration_date" date, "credential_id" varchar, "credential_url" varchar, "created_at" datetime, "updated_at" datetime, "status" varchar not null default ('validated'), "proposed_data" text, "proposed_action" varchar, foreign key("user_id") references users("id") on delete cascade on update no action);
CREATE TABLE "volunteer_experiences" ("id" integer primary key autoincrement not null, "user_id" integer not null, "organization" varchar, "role" varchar, "description" text, "start_date" date, "end_date" date, "created_at" datetime, "updated_at" datetime, "status" varchar not null default ('validated'), "proposed_data" text, "proposed_action" varchar, foreign key("user_id") references users("id") on delete cascade on update no action);
CREATE TABLE "interests" ("id" integer primary key autoincrement not null, "user_id" integer not null, "name" varchar, "created_at" datetime, "updated_at" datetime, "status" varchar not null default ('validated'), "proposed_data" text, "proposed_action" varchar, foreign key("user_id") references users("id") on delete cascade on update no action);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "metiers_code_index" on "metiers" ("code");
CREATE INDEX "skills_code_index" on "skills" ("code");
CREATE UNIQUE INDEX "sectors_label_unique" on "sectors" ("label");
CREATE INDEX "employers_id_forem_index" on "employers" ("id_forem");
CREATE UNIQUE INDEX "sources_code_unique" on "sources" ("code");
CREATE UNIQUE INDEX "benefits_code_unique" on "benefits" ("code");
CREATE UNIQUE INDEX "languages_code_unique" on "languages" ("code");
CREATE UNIQUE INDEX "permits_code_unique" on "permits" ("code");
CREATE UNIQUE INDEX "studies_label_unique" on "studies" ("label");
CREATE UNIQUE INDEX "user_matches_user_id_job_offer_id_unique" on "user_matches" ("user_id", "job_offer_id");
CREATE UNIQUE INDEX "job_offers_forem_id_unique" on "job_offers" ("forem_id");
CREATE UNIQUE INDEX "job_offers_forem_ref_unique" on "job_offers" ("forem_ref");
CREATE INDEX "languages_slug_index" on "languages" ("slug");
CREATE INDEX "skills_slug_index" on "skills" ("slug");
CREATE INDEX "permits_slug_index" on "permits" ("slug");
CREATE INDEX "metiers_slug_index" on "metiers" ("slug");
CREATE INDEX "sectors_slug_index" on "sectors" ("slug");
CREATE INDEX "studies_slug_index" on "studies" ("slug");
CREATE INDEX "profile_messages_session_id_index" on "profile_messages" ("session_id");
CREATE INDEX "idx_sync_priority" on "job_offers" ("status", "is_detailed", "last_seen_at", "detailed_at");
CREATE UNIQUE INDEX "referentiel_metiers_code_unique" on "referentiel_metiers" ("code");
CREATE UNIQUE INDEX "user_ref_unique" on "user_preferred_referentiel" ("user_id", "referentiel_metier_id");
CREATE INDEX "zip_codes_zip_code_index" on "zip_codes" ("zip_code");
CREATE INDEX "zip_codes_city_index" on "zip_codes" ("city");
CREATE INDEX "user_facts_session_id_index" on "user_facts" ("session_id");
CREATE UNIQUE INDEX "user_facts_user_id_local_id_unique" on "user_facts" ("user_id", "local_id");
CREATE INDEX "user_skill_status_index" on "user_skill" ("status");
CREATE INDEX "job_offers_latitude_longitude_index" on "job_offers" ("latitude", "longitude");
CREATE INDEX "job_offers_metier_id_index" on "job_offers" ("metier_id");
CREATE INDEX "job_offers_employer_id_index" on "job_offers" ("employer_id");
CREATE INDEX "job_offers_published_at_index" on "job_offers" ("published_at");
CREATE INDEX "user_matches_pre_score_index" on "user_matches" ("pre_score");
CREATE INDEX "user_matches_final_score_index" on "user_matches" ("final_score");
CREATE INDEX "user_matches_user_id_pre_score_index" on "user_matches" ("user_id", "pre_score");
CREATE INDEX "user_matches_user_id_final_score_index" on "user_matches" ("user_id", "final_score");
